<script>
(()=>{const L=document.getElementById('pgDl');if(!L)return;const ty=L.querySelector('.pgD-ty'),qs=[...document.querySelectorAll('.pgD-q')],rm=matchMedia('(prefers-reduced-motion:reduce)').matches;let busy=false,auto=true,tm;
const stop=()=>{auto=false;clearTimeout(tm)};
const show=qa=>L.scrollTo({top:Math.max(0,qa.offsetTop-L.offsetTop-8),behavior:rm?'auto':'smooth'});
const tot=L.querySelectorAll('.pgD-qa').length,cE=document.getElementById('pgDc'),bE=document.getElementById('pgDb');const mark=k=>{qs.filter(x=>x.dataset.k==k).forEach(x=>x.classList.contains('pgD-qi')?x.classList.add('done'):x.remove());const n=tot-L.querySelectorAll('.pgD-qa[hidden]').length+1;if(cE)cE.textContent=Math.min(n,tot)+' of '+tot+' answered';if(bE)bE.style.width=Math.min(n,tot)/tot*100+'%'};
const ask=(k,byUser)=>{if(byUser)stop();const qa=L.querySelector('.pgD-qa[data-k="'+k+'"]');if(!qa)return;if(!qa.hidden){show(qa);return}if(busy)return;busy=true;mark(k);
 const u=qa.querySelector('.u'),a=qa.querySelector('.b');a.hidden=true;qa.hidden=false;L.insertBefore(qa,ty);u.classList.add('pop');L.scrollTo({top:L.scrollHeight,behavior:rm?'auto':'smooth'});
 setTimeout(()=>{ty.hidden=false;L.scrollTo({top:L.scrollHeight,behavior:rm?'auto':'smooth'});setTimeout(()=>{ty.hidden=true;a.hidden=false;a.classList.add('pop');busy=false;show(qa);if(auto)next()},rm?0:900)},rm?0:350)};
const next=()=>{clearTimeout(tm);const q=[...L.querySelectorAll('.pgD-qa[hidden]')][0];if(q&&auto)tm=setTimeout(()=>ask(q.dataset.k,false),6500)};
qs.forEach(q=>q.addEventListener('click',()=>ask(q.dataset.k,true)));
['wheel','touchstart','keydown'].forEach(e=>L.addEventListener(e,stop,{passive:true}));
const io=new IntersectionObserver(e=>{if(e[0].isIntersecting){io.disconnect();if(!rm)next()}},{threshold:.5});io.observe(L);})();
</script>
